def backtrack(assignment, csp):
    if len(assignment) == len(csp.variables):
        return assignment                      # complete and consistent
    var = select_unassigned_variable(assignment, csp)
    for value in order_domain_values(var, assignment, csp):
        assignment[var] = value
        if csp.consistent(assignment):         # check constraints among assigned vars
            result = backtrack(assignment, csp)
            if result is not None:
                return result
        del assignment[var]                    # undo, try the next value
    return None                                # no value works: backtrack

from collections import deque

def ac3(domains, neighbors, ok, queue=None):
    queue = deque(queue or [(xi, xj) for xi in domains for xj in neighbors[xi]])
    while queue:
        xi, xj = queue.popleft()
        removed = [x for x in domains[xi]
                   if not any(ok(xi, x, xj, y) for y in domains[xj])]
        if removed:
            domains[xi] = [x for x in domains[xi] if x not in removed]
            if not domains[xi]:
                return False               # empty domain: no solution here
            for xk in neighbors[xi]:
                if xk != xj:
                    queue.append((xk, xi))  # xk's supports may be gone
    return True
